import sys
from functools import lru_cache

MOD = 998244353


def normalize(arr):
    vals = sorted(arr)
    mp = {v: i + 1 for i, v in enumerate(vals)}
    return [mp[v] for v in arr]


def decomp_sum_blocks(p):
    n = len(p)
    blocks = []
    start = 0
    mx = 0
    for i, v in enumerate(p, 1):
        if v > mx:
            mx = v
        if mx == i:
            blocks.append((start, i))
            start = i
    if start != n or len(blocks) < 2:
        return None
    return [normalize(p[l:r]) for l, r in blocks]


def decomp_skew_blocks(p):
    n = len(p)
    blocks = []
    start = 0
    mn = n + 1
    for i, v in enumerate(p, 1):
        if v < mn:
            mn = v
        if mn == n - i + 1:
            blocks.append((start, i))
            start = i
    if start != n or len(blocks) < 2:
        return None
    return [normalize(p[l:r]) for l, r in blocks]


def brute_counts(p):
    n = len(p)
    fam = set()
    fam_with_pivot = set()
    full = tuple(range(n))

    for mask in range(1 << n):
        idx = [i for i in range(n) if (mask >> i) & 1]
        ok = True
        for a, b in zip(idx, idx[1:]):
            if p[a] <= p[b]:
                ok = False
                break
        if not ok:
            continue

        surv = []
        for t in range(n):
            alive = True
            pt = p[t]
            for k in idx:
                if t == k:
                    continue
                if (t < k and pt < p[k]) or (t > k and pt > p[k]):
                    alive = False
                    break
            if alive:
                surv.append(t)
        T = tuple(surv)
        fam.add(T)
        if idx:
            fam_with_pivot.add(T)

    F = len(fam) % MOD
    A = len(fam_with_pivot) % MOD
    e = (full in fam_with_pivot)
    return F, A, e


@lru_cache(maxsize=None)
def solve_tuple(tp):
    p = list(tp)
    n = len(p)
    if n == 1:
        return 1, 1, True

    b = decomp_sum_blocks(p)
    if b is not None:
        children = [solve_tuple(tuple(c)) for c in b]
        A = sum(ch[1] for ch in children) % MOD
        F = (1 + A) % MOD
        return F, A, False

    b = decomp_skew_blocks(p)
    if b is not None:
        F = 1
        e = False
        for c in b:
            f, a, ee = solve_tuple(tuple(c))
            F = (F * f) % MOD
            e = e or ee
        A = F if e else (F - 1) % MOD
        return F, A, e

    if n <= 22:
        return brute_counts(p)

    return 0, 0, False


def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))

    arr = [0] * n
    for _ in range(n):
        x = int(next(it))
        y = int(next(it))
        arr[x - 1] = y

    p = normalize(arr)
    ans, _, _ = solve_tuple(tuple(p))
    print(ans % MOD)


