    for i in range(2, int(M ** 0.5) + 1):
        if spf[i] == i:
            for j in range(i * i, M + 1, i):
                if spf[j] == j:
                    spf[j] = i

    # exponents per prime on each edge
    exps = {}  # p -> [v_p(A_1), ..., v_p(A_{N-1})]
    for idx, x0 in enumerate(A):
        x = x0
        while x > 1:
            p = spf[x]
            c = 0
            while x % p == 0:
                x //= p
                c += 1
            if p not in exps:
                exps[p] = [0] * (N - 1)
            exps[p][idx] = c

    ans = 1

    for p, arr in exps.items():
        S = sum(arr)
        if S == 0:
            continue

        g = 0
        for v in arr:
            if v:
                g = v if g == 0 else gcd(g, v)
        if g == 0:
            continue

        # Scale exponents by gcd of steps (only multiples of g can ever touch 0)
        if g > 1:
            arr2 = [v // g for v in arr]
            L = S // g
            base = pow(p, g, MOD)
        else:
            arr2 = arr
            L = S
            base = p

        pw = [1] * (L + 1)
        for i in range(1, L + 1):
            pw[i] = (pw[i - 1] * base) % MOD

        # no[e]: weighted paths up to current index with no zero visited yet
        # yes[e]: weighted paths up to current index with at least one zero visited
        no = [0] * (L + 1)
        yes = [0] * (L + 1)

        yes[0] = 1  # e1 = 0
        for e in range(1, L + 1):
            no[e] = pw[e]  # e1 = e > 0

        for a in arr2:
            nno = [0] * (L + 1)
            nyes = [0] * (L + 1)

            if a == 0:
                for e in range(L + 1):
                    mult = pw[e]
                    v = no[e]
                    if v:
                        nno[e] = (nno[e] + v * mult) % MOD
                    v = yes[e]
                    if v:
                        nyes[e] = (nyes[e] + v * mult) % MOD
            else:
                for e in range(L + 1):
                    v = no[e]
                    if v:
                        t = e + a
                        if t <= L:
                            nno[t] = (nno[t] + v * pw[t]) % MOD
                        t = e - a
                        if t >= 0:
                            if t == 0:
                                nyes[0] = (nyes[0] + v) % MOD  # pw[0] = 1
                            else:
                                nno[t] = (nno[t] + v * pw[t]) % MOD

                    v = yes[e]
                    if v:
                        t = e + a
                        if t <= L:
                            nyes[t] = (nyes[t] + v * pw[t]) % MOD
                        t = e - a
                        if t >= 0:
                            nyes[t] = (nyes[t] + v * pw[t]) % MOD

            no, yes = nno, nyes

        contrib = sum(yes) % MOD
        ans = (ans * contrib) % MOD

    print(ans)

