import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    A = data[1:1+n]

    vmax = max(A) if A else 0

    # phi
    phi = list(range(vmax + 1))
    for p in range(2, vmax + 1):
        if phi[p] == p:
            for k in range(p, vmax + 1, p):
                phi[k] -= phi[k] // p

    # divisors for each value up to vmax
    divisors = [[] for _ in range(vmax + 1)]
    for d in range(1, vmax + 1):
        for m in range(d, vmax + 1, d):
            divisors[m].append(d)

    W = [0] * (vmax + 1)  # W[d] = sum weights of previous elements divisible by d

    ans = 0
    w = 1  # weight for current position i: 2^(i-1)
    out = []

    for x in A:
        s = 0
        for d in divisors[x]:
            s += phi[d] * W[d]
        s %= MOD

        ans = (2 * ans + s) % MOD
        out.append(str(ans))

        for d in divisors[x]:
            W[d] += w
            if W[d] >= MOD:
                W[d] -= MOD

        w <<= 1
        if w >= MOD:
            w %= MOD

    sys.stdout.write("\n".join(out))

