class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        m = len(conflictingPairs)
        ends = [[] for _ in range(n + 1)]

        # Normalize each pair as (x < y), and group by y.
        for idx, (a, b) in enumerate(conflictingPairs):
            x, y = (a, b) if a < b else (b, a)
            ends[y].append((x, idx))

        freq = [0] * (n + 1)        # number of active pairs having left endpoint x
        unique_idx = [-1] * (n + 1) # which pair index if freq[x] == 1
        gain = [0] * m               # additional valid subarrays if removing this pair

        max1 = 0  # largest active x
        max2 = 0  # second largest distinct active x
        base = 0

        for r in range(1, n + 1):
            # Activate pairs with right endpoint r.
            for x, idx in ends[r]:
                freq[x] += 1
                if freq[x] == 1:
                    unique_idx[x] = idx
                elif freq[x] == 2:
                    unique_idx[x] = -1

                if x > max1:
                    max2 = max1
                    max1 = x
                elif max1 > x > max2:
                    max2 = x

            # With all pairs present, valid starts l for this r are l > max1.
            base += r - max1

            # If max1 is contributed by exactly one active pair,
            # removing that pair improves this r by (max1 - max2).
            if max1 > 0 and freq[max1] == 1:
                gain[unique_idx[max1]] += max1 - max2

        return base + (max(gain) if gain else 0)

