            down = 0
            cc = c + 1
            for r2 in range(r + 1, B):
                if rows[r2] >= cc:
                    down += 1
            h = right + down + 1
            prod = (prod * h) % MOD

    return fact * pow(prod, MOD - 2, MOD) % MOD


