import sys

def main() -> None:
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    it = iter(data)
    N = next(it)
    X = next(it)
    processes = []
    for _ in range(N):
        A = next(it)
        P = next(it)
        B = next(it)
        Q = next(it)
        processes.append((A, P, B, Q))

    def min_cost_for_capacity(A: int, P: int, B: int, Q: int, k: int) -> int:
        best = 10**30

        # Try small number of S-machines; complete with T-machines.
        for s in range(B + 1):
            rem = k - A * s
            if rem <= 0:
                cost = P * s
            else:
                t = (rem + B - 1) // B
                cost = P * s + Q * t
            if cost < best:
                best = cost

        # Try small number of T-machines; complete with S-machines.
        for t in range(A + 1):
            rem = k - B * t
            if rem <= 0:
                cost = Q * t
            else:
                s = (rem + A - 1) // A
                cost = Q * t + P * s
            if cost < best:
                best = cost

        return best

    def feasible(k: int) -> bool:
        total = 0
        for A, P, B, Q in processes:
            total += min_cost_for_capacity(A, P, B, Q, k)
            if total > X:
                return False
        return True

    # Binary search the maximum feasible minimum capacity.
    lo, hi = 0, 10**9 + 1  # [lo, hi)
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid

    print(lo)

if __name__ == "__main__":
    main()

