def fast(A,P,B,Q,k):
    best=10**18
    for s in range(B+1):
        rem=k-A*s
        if rem<=0:c=P*s
        else:c=P*s+((rem+B-1)//B)*Q
        best=min(best,c)
    for t in range(A+1):
        rem=k-B*t
        if rem<=0:c=Q*t
        else:c=Q*t+((rem+A-1)//A)*P
        best=min(best,c)
    return best

def brute(A,P,B,Q,k):
    best=10**18
    # upper bounds coarse
    for s in range(0, k//A+3):
        for t in range(0, k//B+3):
            if A*s+B*t>=k:
                best=min(best,P*s+Q*t)
    return best

