from functools import lru_cache

class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        L = len(s)

        # At most 0 operations means the number must already be 1.
        if k == 0:
            return 0 if s == "1" else 1

        # Binomial coefficients C[n][r] for 0 <= n,r <= L
        C = [[0] * (L + 1) for _ in range(L + 1)]
        for n in range(L + 1):
            C[n][0] = C[n][n] = 1
            for r in range(1, n):
                C[n][r] = (C[n - 1][r - 1] + C[n - 1][r]) % MOD

        # cnt[m] = count of numbers x in [0, n-1] with popcount(x) = m
        cnt = [0] * (L + 1)
        used = 0
        for i, ch in enumerate(s):
            if ch == '1':
                rem = L - i - 1
                # Put 0 at this bit (making number smaller), choose any ones in suffix
                for need in range(rem + 1):
                    cnt[used + need] = (cnt[used + need] + C[rem][need]) % MOD
                # Continue tight with bit 1
                used += 1

        @lru_cache(None)
        def steps_to_one(v: int) -> int:
            if v == 1:
                return 0
            return 1 + steps_to_one(v.bit_count())

        ans = 0
        # For x > 1: steps(x) = 1 + steps_to_one(popcount(x))
        # So require steps_to_one(popcount(x)) <= k-1.
        # x=1 is also included here when popcount=1, and is valid for all k>=1.
        for m in range(1, L + 1):
            if steps_to_one(m) <= k - 1:
                ans = (ans + cnt[m]) % MOD

        return ans

