import sys
from bisect import bisect_left, bisect_right

INF = 10**9

class RangeMin2DCaseA:
    def __init__(self, points):
        ls = sorted({l for l, _ in points})
        self.coords = ls
        self.k = len(ls)
        sz = 1
        while sz < self.k:
            sz <<= 1
        self.size = sz
        nnode = 2 * sz
        buckets = [[] for _ in range(nnode)]
        pos_cache = {}
        for l, r in points:
            p = pos_cache.get(l)
            if p is None:
                p = bisect_left(ls, l)
                pos_cache[l] = p
            i = p + sz
            while i:
                buckets[i].append(r)
                i >>= 1
        self.rs = [None] * nnode
        self.bit = [None] * nnode
        for i in range(1, nnode):
            if buckets[i]:
                arr = sorted(set(buckets[i]))
                self.rs[i] = arr
                self.bit[i] = [INF] * (len(arr) + 1)

    @staticmethod
    def bit_upd(bit, i, v):
        n = len(bit)
        while i < n:
            if v < bit[i]:
                bit[i] = v
            i += i & -i

    @staticmethod
    def bit_q(bit, i):
        res = INF
        while i > 0:
            x = bit[i]
            if x < res:
                res = x
            i -= i & -i
        return res

    def add(self, l, r, idx):
        p = bisect_left(self.coords, l)
        if p >= self.k or self.coords[p] != l:
            return
        i = p + self.size
        while i:
            arr = self.rs[i]
            if arr is not None:
                rk = bisect_left(arr, r) + 1
                rev = len(arr) - rk + 1
                self.bit_upd(self.bit[i], rev, idx)
            i >>= 1

    def node_query(self, node, x):
        arr = self.rs[node]
        if arr is None:
            return INF
