            return INF
        li = bisect_left(self.coords, L)
        ri = bisect_right(self.coords, R) - 1
        if li > ri:
            return INF
        l = li + self.size
        r = ri + self.size
        ans = INF
        while l <= r:
            if l & 1:
                v = self.node_query(l, x)
                if v < ans:
                    ans = v
                l += 1
            if not (r & 1):
                v = self.node_query(r, x)
                if v < ans:
                    ans = v
                r -= 1
            l >>= 1
            r >>= 1
        return ans


def compute_caseA_next(M, tval, L, R, types):
    points = [(L[i], R[i]) for i in range(1, M + 1) if types[i] == tval]
    ds = RangeMin2DCaseA(points)
    nxt = [INF] * (M + 1)
    for i in range(M, 0, -1):
        if types[i] == tval:
            nxt[i] = ds.query(L[i] + 1, R[i] - 1, R[i])
            ds.add(L[i], R[i], i)
    return nxt


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    it = iter(data)
    N = next(it); M = next(it); Q = next(it)

    L = [0] * (M + 1)
    R = [0] * (M + 1)
    types = [0] * (M + 1)

    for i in range(1, M + 1):
        s = next(it); t = next(it)
        if s < t:
            types[i] = 1; L[i] = s; R[i] = t
        else:
            types[i] = -1; L[i] = t; R[i] = s

    nxt = [INF] * (M + 1)

    byL = {}
    byR = {}
    for i in range(1, M + 1):
        byL.setdefault(L[i], []).append(i)
        byR.setdefault(R[i], []).append(i)
    for arr in byL.values():
        for a, b in zip(arr, arr[1:]):
            if b < nxt[a]: nxt[a] = b
    for arr in byR.values():
        for a, b in zip(arr, arr[1:]):
            if b < nxt[a]: nxt[a] = b

    for tval in (1, -1):
        na = compute_caseA_next(M, tval, L, R, types)
        for i in range(1, M + 1):
            if na[i] < nxt[i]:
                nxt[i] = na[i]

    Lm = [0] * (M + 1)
    Rm = [0] * (M + 1)
    for i in range(1, M + 1):
        Lm[i] = N + 1 - R[i]
        Rm[i] = N + 1 - L[i]
    for tval in (1, -1):
        nb = compute_caseA_next(M, tval, Lm, Rm, types)
        for i in range(1, M + 1):
            if nb[i] < nxt[i]:
                nxt[i] = nb[i]

    sz = 1
    while sz < M:
        sz <<= 1
    seg = [INF] * (2 * sz)
    for i in range(1, M + 1):
        seg[sz + i - 1] = nxt[i]
    for i in range(sz - 1, 0, -1):
        seg[i] = seg[i << 1] if seg[i << 1] < seg[i << 1 | 1] else seg[i << 1 | 1]

    out = []
    for _ in range(Q):
        l = next(it); r = next(it)
        l0 = l - 1 + sz
        r0 = r - 1 + sz
        mn = INF
        while l0 <= r0:
            if l0 & 1:
                v = seg[l0]
                if v < mn: mn = v
                l0 += 1
            if not (r0 & 1):
                v = seg[r0]
                if v < mn: mn = v
                r0 -= 1
            l0 >>= 1; r0 >>= 1
        out.append('No' if mn <= r else 'Yes')

    sys.stdout.write('\n'.join(out))

