class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2

        # pow10[i] = 10^i mod k
        pow10 = [0] * n
        pow10[0] = 1 % k
        for i in range(1, n):
            pow10[i] = (pow10[i - 1] * 10) % k

        # Weight of choosing digit at position p in the left half:
        # contribution to full palindrome modulo k.
        w = [0] * m
        for p in range(m):
            q = n - 1 - p
            if p == q:  # middle digit (only when n is odd)
                w[p] = pow10[p]
            else:
                w[p] = (pow10[p] + pow10[q]) % k

        # dp mask transition precompute:
        # trans[ww][mask] = reachable residues after adding one digit with weight ww,
        # when suffix residues are represented by 'mask'.
        max_mask = 1 << k
        trans = [[0] * max_mask for _ in range(k)]
        for ww in range(k):
            adds = [(d * ww) % k for d in range(10)]
            for mask in range(max_mask):
                out = 0
                mm = mask
                while mm:
                    b = mm & -mm
                    r = b.bit_length() - 1
                    mm -= b
                    for a in adds:
                        out |= 1 << ((r + a) % k)
                trans[ww][mask] = out

        # dp[p]: bitmask of residues achievable by positions p..m-1
        dp = [0] * (m + 1)
        dp[m] = 1 << 0
        for p in range(m - 1, -1, -1):
            dp[p] = trans[w[p]][dp[p + 1]]

        # Greedily build largest lexicographic left half with feasibility checks.
        half = []
        cur = 0
        for p in range(m):
            low = 1 if p == 0 else 0  # no leading zero
            wp = w[p]
            for d in range(9, low - 1, -1):
                nm = (cur + d * wp) % k
                need = (-nm) % k
                if (dp[p + 1] >> need) & 1:
                    half.append(str(d))
                    cur = nm
