class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        A, B, C = p.split('*')  # exactly 2 '*'
        n = len(s)
        INF = 10**9

        def kmp_occ(text: str, pat: str):
            """Return boolean array occ where occ[i] is True iff pat occurs at text[i:]."""
            m = len(pat)
            if m == 0:
                return None

            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and pat[i] != pat[j]:
                    j = pi[j - 1]
                if pat[i] == pat[j]:
                    j += 1
                    pi[i] = j

            occ = [False] * (n + 1)
            j = 0
            for i, ch in enumerate(text):
                while j and ch != pat[j]:
                    j = pi[j - 1]
                if ch == pat[j]:
                    j += 1
                    if j == m:
                        occ[i - m + 1] = True
                        j = pi[j - 1]
            return occ

        def build_next(seg: str):
            """next_pos[i] = smallest j >= i where seg starts in s, else INF."""
            m = len(seg)
            if m == 0:
                return list(range(n + 1))  # empty string occurs at every boundary

            occ = kmp_occ(s, seg)
            nxt = [INF] * (n + 1)
            for i in range(n - 1, -1, -1):
                nxt[i] = i if occ[i] else nxt[i + 1]
            return nxt

        nextB = build_next(B)
        nextC = build_next(C)
        lenA, lenB, lenC = len(A), len(B), len(C)

        def length_if_start_at(l: int) -> int:
            # A must start exactly at l (or empty)
            pos_after_A = l + lenA
            if pos_after_A > n:
                return INF

            b = nextB[pos_after_A]
            if b >= INF:
                return INF

            pos_after_B = b + lenB
            if pos_after_B > n:
                return INF

            c = nextC[pos_after_B]
            if c >= INF:
                return INF

            return (c + lenC) - l

        ans = INF

        if lenA == 0:
            # Pattern starts with '*': l can be any boundary
            for l in range(n + 1):
                cur = length_if_start_at(l)
                if cur < ans:
                    ans = cur
        else:
            occA = kmp_occ(s, A)
            limit = n - lenA
            for l in range(limit + 1):
                if occA[l]:
                    cur = length_if_start_at(l)
                    if cur < ans:
                        ans = cur

        return -1 if ans >= INF else ans

