import random
from functools import lru_cache

class Solution:
    def maxEnergyBoost(self, A, B):
        n=len(A)
        fa=[0]*n;fb=[0]*n
        fa[0]=A[0];fb[0]=B[0]
        fa[1]=fa[0]+A[1];fb[1]=fb[0]+B[1]
        for i in range(2,n):
            fa[i]=A[i]+max(fa[i-1],fb[i-2])
            fb[i]=B[i]+max(fb[i-1],fa[i-2])
        return max(fa[-1],fb[-1])

def brute(A,B):
    n=len(A)
    @lru_cache(None)
    def dfs(i,prev):
        if i==n:return 0
        ans=dfs(i+1,0)  # cleanse
        if prev in (0,1): ans=max(ans,A[i]+dfs(i+1,1))
        if prev in (0,2): ans=max(ans,B[i]+dfs(i+1,2))
        return ans
    return dfs(0,0)

sol=Solution()
