import math


def sieve(n: int):
    if n < 2:
        return []
    is_prime = bytearray(b"\x01") * (n + 1)
    is_prime[0:2] = b"\x00\x00"
    limit = int(n ** 0.5)
    for p in range(2, limit + 1):
        if is_prime[p]:
            start = p * p
            is_prime[start:n + 1:p] = b"\x00" * (((n - start) // p) + 1)
    return [i for i in range(2, n + 1) if is_prime[i]]


def main():
    N = int(sys.stdin.buffer.read())

    # For n = p^2 q^2, need p*q <= sqrt(N)
    M = math.isqrt(N)
    primes = sieve(M)

    # Count n = p^8
    ans = 0
    for p in primes:
        if p ** 8 <= N:
            ans += 1
        else:
            break

    # Count n = p^2 q^2 with distinct primes p < q
    j = len(primes) - 1
    for i, p in enumerate(primes):
        while i < j and p * primes[j] > M:
            j -= 1
        if j <= i:
            break
        ans += j - i

    print(ans)


