from typing import List

class Solution:
    def countPairs(self, nums: List[int]) -> int:
        cache = {}

        def reachable(x: int):
            """All integer values obtainable from x with at most one digit swap."""
            if x in cache:
                return cache[x]

            s = list(str(x))
            m = len(s)
            vals = {x}  # zero swap

            for i in range(m):
                for j in range(i + 1, m):
                    s[i], s[j] = s[j], s[i]
                    vals.add(int("".join(s)))  # leading zeros naturally handled by int()
                    s[i], s[j] = s[j], s[i]

            cache[x] = vals
            return vals

        n = len(nums)
        ans = 0

        for i in range(n):
            a = nums[i]
            ra = reachable(a)
            for j in range(i + 1, n):
                b = nums[j]
                if b in ra or a in reachable(b):
                    ans += 1

        return ans

