def brute(nums):
    n=len(nums)
    from functools import lru_cache
    @lru_cache(None)
    def dp(i):
        if i==n-1:return 0
        m=0
        for j in range(i+1,n):
            m=max(m,(j-i)*nums[i]+dp(j))
        return m
    return dp(0)

