            return 0

        max_need = max(nums)
        mask = (1 << (max_need + 1)) - 1

        # dp[i]: bitset of reachable sums for index i
        dp = [1] * n  # only sum 0 reachable initially

        for k, (l, r, val) in enumerate(queries, 1):
            for i in range(l, r + 1):
