import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        sn, sm = str(n), str(m)
        if len(sn) != len(sm):
            return -1

        d = len(sn)
        limit = 10 ** d

        # Sieve primes in [0, limit)
        is_prime = [True] * limit
        if limit > 0:
            is_prime[0] = False
        if limit > 1:
            is_prime[1] = False
        p = 2
        while p * p < limit:
            if is_prime[p]:
                start = p * p
                is_prime[start:limit:p] = [False] * (((limit - 1 - start) // p) + 1)
            p += 1

        # Every number along the path (including endpoints) must be non-prime.
        if is_prime[n] or is_prime[m]:
            return -1

        # Dijkstra on numbers with fixed digit count d.
        # Node cost contributes its numeric value; initial cost includes n.
        INF = 10**30
        dist = [INF] * limit
        dist[n] = n
        pq = [(n, n)]  # (total_cost, current_value)

        pow10 = [10 ** i for i in range(d)]

        while pq:
            cost, x = heapq.heappop(pq)
            if cost != dist[x]:
                continue
            if x == m:
                return cost

            for p10 in pow10:
                digit = (x // p10) % 10

                if digit < 9:
                    y = x + p10
                    if not is_prime[y]:
                        nc = cost + y
                        if nc < dist[y]:
                            dist[y] = nc
                            heapq.heappush(pq, (nc, y))

                if digit > 0:
                    y = x - p10
                    if not is_prime[y]:
                        nc = cost + y
                        if nc < dist[y]:
                            dist[y] = nc
                            heapq.heappush(pq, (nc, y))

        return -1

