class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        # lcp[i][j] = LCP length of nums[i:] and nums[j:]
        # Use unsigned short since n <= 5000.
        lcp = [array('H', [0]) * (n + 1) for _ in range(n + 1)]

        for i in range(n - 1, -1, -1):
            row = lcp[i]
            next_row = lcp[i + 1]
            ai = nums[i]
            for j in range(n - 1, i - 1, -1):
                if ai == nums[j]:
                    row[j] = next_row[j + 1] + 1

        row0 = lcp[0]

        # Splits where nums1 is prefix of nums2
        count1 = 0
        for i in range(1, n - 1):
            if row0[i] >= i:
                add = n - (i << 1)  # j from 2*i to n-1
                if add > 0:
                    count1 += add

        # Splits where nums2 is prefix of nums3
        # Also count overlap with condition1 to apply inclusion-exclusion.
        count2 = 0
        both = 0
        for i in range(1, n - 1):
            rowi = lcp[i]
            half = (n - i) >> 1  # k = len(nums2), need k <= len(nums3)
            cond1_i = row0[i] >= i

            for k in range(1, half + 1):
                # j = i + k, check nums[i:j] == nums[j:j+k]
                if rowi[i + k] >= k:
                    count2 += 1
                    # Also satisfies condition1 when j >= 2*i <=> k >= i
                    if cond1_i and k >= i:
                        both += 1

        return count1 + count2 - both

