import sys

def can_within_one(s: str, t: str) -> bool:
    n, m = len(s), len(t)
    if abs(n - m) > 1:
        return False

    if n == m:
        diff = 0
        for a, b in zip(s, t):
            if a != b:
                diff += 1
                if diff > 1:
                    return False
        return True

    # Make s the shorter one (length differs by exactly 1 here)
    if n > m:
        s, t = t, s
        n, m = m, n

    i = j = 0
    skipped = 0
    while i < n and j < m:
        if s[i] == t[j]:
            i += 1
            j += 1
        else:
            skipped += 1
            if skipped > 1:
                return False
            j += 1  # skip one char in the longer string

    return True


