from typing import List
from collections import deque

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Since threshold >= 1, the out-degree cap is not restrictive:
        # if every node can reach 0, we can keep only one outgoing edge per node
        # along a path to 0 and still satisfy reachability.

        if n == 1:
            return 0

        max_w = 0
        for a, b, w in edges:
            if w > max_w:
                max_w = w

        def feasible(limit: int) -> bool:
            # Keep only edges with w <= limit and check if all nodes can reach 0.
            # Equivalent to checking if all nodes are reachable from 0 in reversed graph.
            rev = [[] for _ in range(n)]
            for a, b, w in edges:
                if w <= limit:
                    rev[b].append(a)

            seen = [False] * n
            q = deque([0])
            seen[0] = True
            reached = 1

            while q:
                u = q.popleft()
                for v in rev[u]:
                    if not seen[v]:
                        seen[v] = True
                        reached += 1
                        q.append(v)

            return reached == n

        # If even with all edges it's impossible, answer is -1.
        if not feasible(max_w):
            return -1

        # Binary search minimum feasible maximum weight.
        lo, hi = 1, max_w
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1

        return lo

