        # where house k has color a and house n-1-k has color b.
        dp = [[INF] * 3 for _ in range(3)]

        # Initialize with outermost pair (0, n-1)
        for a in range(3):
            for b in range(3):
                if a != b:  # equidistant constraint
                    dp[a][b] = cost[0][a] + cost[n - 1][b]

        # Process inward pairs
        for k in range(1, m):
            i, j = k, n - 1 - k
            ndp = [[INF] * 3 for _ in range(3)]

            for a in range(3):
                left_cost = cost[i][a]
                for b in range(3):
                    if a == b:  # equidistant constraint for current pair
                        continue

                    add = left_cost + cost[j][b]
                    best_prev = INF

                    # previous pair colors (pa, pb) must differ from current
                    # due to adjacency on left and right chains.
                    for pa in range(3):
                        if pa == a:
                            continue
                        row = dp[pa]
                        for pb in range(3):
                            if pb == b:
                                continue
                            val = row[pb]
                            if val < best_prev:
                                best_prev = val

                    ndp[a][b] = add + best_prev

            dp = ndp

        ans = INF
        for a in range(3):
            for b in range(3):
                if a != b and dp[a][b] < ans:
                    ans = dp[a][b]
        return ans

