import sys

def solve() -> None:
    data = list(map(int, sys.stdin.buffer.read().split()))
    it = iter(data)

    N = next(it)
    W = next(it)

    cols = [[] for _ in range(W + 1)]
    for i in range(1, N + 1):
        x = next(it)
        y = next(it)
        cols[x].append((y, i))

    INF = 10**30
    m = INF
    for x in range(1, W + 1):
        cols[x].sort()  # by y ascending
        lx = len(cols[x])
        if lx < m:
            m = lx
    if m == INF:
        m = 0

    rank = [0] * (N + 1)  # rank in its column (1-based from bottom initially)
    if m > 0:
        maxY = [0] * (m + 1)
    else:
        maxY = [0]

    for x in range(1, W + 1):
        c = cols[x]
        for k, (y, bid) in enumerate(c, 1):
            rank[bid] = k
            if k <= m and y > maxY[k]:
                maxY[k] = y

    clear_time = [0] * (m + 1)  # clear_time[k]: time when k-th full-row deletion happens
    cur = 0
    for k in range(1, m + 1):
        v = maxY[k]
        if cur + 1 > v:
            cur = cur + 1
        else:
            cur = v
        clear_time[k] = cur

    Q = next(it)
    out = []
    for _ in range(Q):
        T = next(it)
        A = next(it)
        k = rank[A]
        if k <= m and clear_time[k] <= T:
            out.append("No")
        else:
            out.append("Yes")

    sys.stdout.write("\n".join(out))

