class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        base = s.count('1')

        t = '1' + s + '1'
        runs = []  # (char, length)
        i = 0
        m = len(t)
        while i < m:
            j = i + 1
            while j < m and t[j] == t[i]:
                j += 1
            runs.append((t[i], j - i))
            i = j

        zmax = 0
        for ch, ln in runs:
            if ch == '0' and ln > zmax:
                zmax = ln

        best_gain = 0

        # removable 1-run: surrounded by 0-runs on both sides
        for k in range(1, len(runs) - 1):
            ch, a = runs[k]
            if ch != '1':
                continue
            if runs[k - 1][0] == '0' and runs[k + 1][0] == '0':
                l = runs[k - 1][1]
                r = runs[k + 1][1]
                gain = max(l + r, zmax - a)
                if gain > best_gain:
                    best_gain = gain

        return base + best_gain

