class Solution:
    def calculateScore(self, s: str) -> int:
        stacks = [[] for _ in range(26)]  # unmarked indices per character
        score = 0
        base = ord('a')

        for i, ch in enumerate(s):
            x = ord(ch) - base
            mirror = 25 - x  # mirror index in reversed alphabet

            if stacks[mirror]:
                j = stacks[mirror].pop()  # closest unmarked mirror index (< i)
                score += i - j
            else:
                stacks[x].append(i)  # keep as unmarked candidate

        return score

