class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vowels = {"a", "e", "i", "o", "u"}

        def at_most(K: int) -> int:
            if K < 0:
                return 0

            last_pos = {v: -1 for v in vowels}
            left = 0
            consonants = 0
            total = 0

            for right, ch in enumerate(word):
                if ch in vowels:
                    last_pos[ch] = right
                else:
                    consonants += 1

                while consonants > K:
                    if word[left] not in vowels:
                        consonants -= 1
                    left += 1

                # Earliest index among the latest seen positions of all 5 vowels
                earliest_all_vowels = min(last_pos.values())

                # Valid starts are [left .. earliest_all_vowels]
                if earliest_all_vowels >= left:
                    total += earliest_all_vowels - left + 1

            return total

        # exactly k = at most k - at most (k-1)
        return at_most(k) - at_most(k - 1)

