class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        n = len(points)
        point_set = {(x, y) for x, y in points}
        best = -1

        for i in range(n):
            x1, y1 = points[i]
            for j in range(i + 1, n):
                x2, y2 = points[j]

                # Need opposite corners of an axis-aligned rectangle
                if x1 == x2 or y1 == y2:
                    continue

                lx, rx = (x1, x2) if x1 < x2 else (x2, x1)
                by, ty = (y1, y2) if y1 < y2 else (y2, y1)

                corners = {(lx, by), (lx, ty), (rx, by), (rx, ty)}
                if not all(c in point_set for c in corners):
                    continue

                # No other point may lie inside or on border of this rectangle
                valid = True
                for x, y in points:
                    if (x, y) in corners:
                        continue
                    if lx <= x <= rx and by <= y <= ty:
                        valid = False
                        break

                if valid:
                    area = (rx - lx) * (ty - by)
                    if area > best:
                        best = area

        return best

