from typing import List

class Solution:
    def countArrays(self, original: List[int], bounds: List[List[int]]) -> int:
        # copy[i] must equal original[i] + k for a single integer shift k.
        # For each i: bounds[i][0] <= original[i] + k <= bounds[i][1]
        # => bounds[i][0] - original[i] <= k <= bounds[i][1] - original[i]
        # The answer is the size of the intersection of all such intervals.
        lo = -10**30
        hi = 10**30

        for x, (u, v) in zip(original, bounds):
            lo = max(lo, u - x)
            hi = min(hi, v - x)

        return max(0, hi - lo + 1)

